      sp->winCap_jFull = (int)(lookbackFull + 1);
      if( sp->winCap_jFull < 1 || sp->winCap_jFull > historyLen ) { if( dRing != &local_dRing[0] ) { TA_Free( dRing ); } TA_HMA_ReleaseImpl( sp ); return TA_INTERNAL_ERROR(320); }
